import { Texture, type Scene, type ShaderMaterial } from "@babylonjs/core";
import type { CelestialBody } from "@bridge-sim/shared";

/**
 * Optional production-art hook. Artists can add equirectangular PNG/JPEG/WebP
 * files under src/assets/planets/<system-body-id>/ without changing source.
 *
 * All sources are bundled by Vite (and work offline). When no authored asset
 * exists, the procedural textures already generated by PlanetTextures remain.
 * A failed asset load also preserves that procedural fallback.
 *
 * Conventions:
 *   albedo.(png|jpg|webp) - sRGB surface colour, 2:1 aspect
 *   clouds.png           - RGBA cloud colour/density, 2:1 aspect
 *   night.png            - R city-light intensity, G ocean-reflectance mask
 *
 * The names intentionally use a celestial BODY id, so the same renderer
 * supports a catalog of unrelated star systems without special-casing Haven.
 */
const textures = import.meta.glob<{ default: string }>(
  "./assets/planets/*/*.{png,jpg,jpeg,webp}",
  { eager: true, query: "?url", import: "default" }
);

function locate(bodyId: string, channel: string): string | null {
  const prefix = "./assets/planets/" + bodyId + "/" + channel + ".";
  for (const [path, resource] of Object.entries(textures)) {
    if (path.startsWith(prefix)) return resource.default;
  }
  return null;
}

export function attachAuthoredPlanetTextures(
  scene: Scene, body: CelestialBody,
  surfaceMaterial: ShaderMaterial, cloudMaterial: ShaderMaterial | null
): void {
  const channels = [
    { name: "albedo", sampler: "surfaceSampler", target: surfaceMaterial },
    { name: "night", sampler: "nightSampler", target: surfaceMaterial },
    { name: "clouds", sampler: "cloudSampler", target: cloudMaterial }
  ] as const;
  for (const channel of channels) {
    if (!channel.target) continue;
    const url = locate(body.id, channel.name);
    if (!url) continue;
    const texture = new Texture(url, scene, false, false,
      Texture.TRILINEAR_SAMPLINGMODE,
      () => {
        texture.wrapU = Texture.WRAP_ADDRESSMODE;
        texture.wrapV = Texture.CLAMP_ADDRESSMODE;
        texture.hasAlpha = channel.name === "clouds";
        channel.target!.setTexture(channel.sampler, texture);
      },
      (_message, _exception) => {
        console.warn("Planet art asset unavailable, keeping generated fallback:", body.id, channel.name);
        texture.dispose();
      }
    );
  }
}
